package com.sathavahana.kalamkari.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="coupons") public class Coupon { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String code; @Enumerated(EnumType.STRING) DiscountType discountType; BigDecimal discountValue; BigDecimal minimumOrderAmount=BigDecimal.ZERO; BigDecimal maximumDiscountAmount; Integer usageLimit; int usedCount; int perCustomerLimit=1; boolean active=true; Instant startsAt; Instant expiresAt; public enum DiscountType{PERCENTAGE,FLAT} public Coupon(){} public String getCode(){return code;} public BigDecimal discount(BigDecimal total){if(discountType==DiscountType.PERCENTAGE)return total.multiply(discountValue).divide(BigDecimal.valueOf(100));return discountValue;} public boolean usable(BigDecimal total){Instant n=Instant.now();return active&&total.compareTo(minimumOrderAmount)>=0&&(usageLimit==null||usedCount<usageLimit)&&(startsAt==null||!n.isBefore(startsAt))&&(expiresAt==null||n.isBefore(expiresAt));} public void use(){usedCount++;} }
